  const userlyticsHeading = headings.find(h => h.textContent.includes('Userlytics'));
  if (!userlyticsHeading) return "Heading not found";
  let cur = userlyticsHeading;
  let text = [cur.textContent];
  for (let i = 0; i < 10; i++) {
    cur = cur.nextElementSibling;
    if (!cur || cur.tagName.startsWith('H')) break;
    text.push(cur.textContent);
  }
  return text.join('\n');
});
